const std::array<std::uint8_t, 32>& real_key() {
  static const auto k = key32(kPk1Hex);
  return k;
}
const std::array<std::uint8_t, 32>& decoy_key() {
  static const auto k = key32(kPk2Hex);
  return k;
}

std::string envelope_with(std::string_view replaced_manifest) {
  const auto cut = kGoodEnvelope.find("\n--STRATA-SIGNATURE-V1\n");
  return std::string(replaced_manifest) + std::string(kGoodEnvelope.substr(cut));
}

bool rejected_as(std::string_view envelope, const secure_frontend::ReleaseReject want, const std::string& what) {
  const auto result = secure_frontend::verify_release_manifest(envelope, real_key());
  const auto* issue = std::get_if<secure_frontend::ReleaseIssue>(&result);
  if (issue == nullptr) {
    expect(false, "must reject: " + what);
    return false;
  }
  if (issue->reject != want) {
    expect(false, "wrong reject reason: " + what);
    return false;
  }
  return true;
}

void case_good_envelope_verifies() {
  const auto result = secure_frontend::verify_release_manifest(kGoodEnvelope, real_key());
  const auto* manifest = std::get_if<secure_frontend::ReleaseManifest>(&result);
  expect(manifest != nullptr, "good envelope must verify");
  if (manifest == nullptr) return;
  expect(manifest->version == "0.9.4", "version parsed");
  expect(manifest->channel == "stable", "channel parsed");
  expect(manifest->components.size() == 3, "three components");
  if (manifest->components.size() != 3) return;
  expect(manifest->components[0].name == "frontend", "component 0 name");
  expect(manifest->components[0].file == "strata-frontend-0.9.4-x86_64.tar.zst", "component 0 file");
  expect(manifest->components[0].size == 112631296ULL, "component 0 size");
  expect(manifest->components[0].sha256 == "3a7f21c0d5e9b8f46a10c7d2e5f8014b9c6d3e2f1a0b5c8d9e4f7a6b3c2d1e0f",
         "component 0 sha256");
  expect(manifest->components[0].notes_url == "https://releases.strata.invalid/0.9.4/frontend.html",
         "component 0 notes_url");
  expect(manifest->components[2].name == "cuda-runtime", "component 2 name");
  expect(manifest->components[2].size == 308219904ULL, "component 2 size");
  expect(manifest->manifest_bytes == kManifest, "manifest bytes preserved verbatim");
}

void case_tampered_manifest_rejected() {
  expect(rejected_as(kTamperedManifestEnv, secure_frontend::ReleaseReject::signature_invalid,
                     "manifest tampered one byte"),
         "tampered manifest rejected by the signature");
}

void case_tampered_signature_rejected() {
  expect(rejected_as(kTamperedSignatureEnv, secure_frontend::ReleaseReject::signature_invalid,
                     "signature byte flipped (valid base64)"),
         "tampered signature rejected");
}

void case_wrong_pinned_key_rejected() {
  const auto result = secure_frontend::verify_release_manifest(kGoodEnvelope, decoy_key());
  const auto* issue = std::get_if<secure_frontend::ReleaseIssue>(&result);
  expect(issue != nullptr && issue->reject == secure_frontend::ReleaseReject::signature_invalid,
         "a real-but-wrong Ed25519 key must not be trusted");
}

void case_no_pinned_key_refuses_exact_line() {
  const auto result = secure_frontend::verify_release_manifest_pinned(kGoodEnvelope);
  const auto* issue = std::get_if<secure_frontend::ReleaseIssue>(&result);
  expect(issue != nullptr && issue->reject == secure_frontend::ReleaseReject::no_pinned_key,
         "unpinned build refuses");
  if (issue != nullptr) {
    expect(secure_frontend::describe_release_issue(*issue) == "no release key pinned",
           "the refusal line is exact");
  }
  expect(!secure_frontend::pinned_release_public_key().has_value(), "no key is pinned in the default build");
}

void case_python_signed_fixture_verifies() {
  const auto& args = secure_frontend_test::extra_arguments();
  expect(!args.empty(), "the tests/fixtures directory is passed as ARGS");
  if (args.empty()) return;
  const std::filesystem::path dir{std::filesystem::path{args.front()} / "release"};
  std::error_code ec;
  if (!std::filesystem::exists(dir / "signed-envelope.txt", ec)) {
    expect(false, "the committed fixture tests/fixtures/release/signed-envelope.txt exists");
    return;
  }
  const std::string envelope = secure_frontend_test::read_file(dir / "signed-envelope.txt");
  expect(envelope == std::string(kGoodEnvelope),
         "the Python-signed fixture bytes equal the RFC-reference envelope this suite pins verbatim");
  std::string published = secure_frontend_test::read_file(dir / "pubkey.hex");
  published.erase(std::remove(published.begin(), published.end(), '\n'), published.end());
  expect(published == std::string(kPk1Hex), "the fixture-published key is the RFC vector-1 key");
  const auto result = secure_frontend::verify_release_manifest(envelope, key32(published));
  expect(std::holds_alternative<secure_frontend::ReleaseManifest>(result), "the C++ verifier accepts the signature made by scripts/release/sign.py");
  if (auto* manifest = std::get_if<secure_frontend::ReleaseManifest>(&result)) expect(manifest->version == "0.9.4", "the fixture version");
}

void case_malformed_envelopes_rejected() {
  const std::string no_marker = std::string(kManifest) + "\n";
  rejected_as(no_marker, secure_frontend::ReleaseReject::framing, "envelope without the framing line");
  rejected_as(std::string(kGoodEnvelope) + "--STRATA-SIGNATURE-V1\n", secure_frontend::ReleaseReject::framing,
              "second framing marker");
  const auto cut = kGoodEnvelope.find("\n--STRATA-SIGNATURE-V1\n");
  const std::string head{kGoodEnvelope.substr(0, cut + 23)};
  rejected_as(head + "!!78==\n", secure_frontend::ReleaseReject::signature_base64, "base64 alphabet violated");
  rejected_as(head + "abc", secure_frontend::ReleaseReject::signature_base64, "base64 padding/length invalid");
  rejected_as(head + "YWJjZA== junk\n", secure_frontend::ReleaseReject::framing, "junk after the signature line");
  const std::string bad_json = std::string(kManifest).substr(0, kManifest.find("\"components\"")) + "}";
  const std::string bad_json_env = envelope_with(bad_json);
  rejected_as(bad_json_env, secure_frontend::ReleaseReject::json, "manifest JSON malformed");
  rejected_as(envelope_with(R"DUP({"format":"strata-release-v1","format":"strata-release-v1"})DUP"),
              secure_frontend::ReleaseReject::json, "duplicate JSON keys rejected");
}

